cd /workspace && cat > compile.sh << 'EOF'
#!/bin/bash
set -e

# Compile script for xz implementation
# This builds an executable that wraps the Python implementation

# Ensure we have Python3
if ! command -v python3 &> /dev/null; then
    echo "Python3 not found" >&2
    exit 1
fi

# Copy the Python implementation
cp xz_impl.py /tmp/xz_impl.py

# Create a wrapper script
cat > /tmp/xz_wrapper.sh << 'WRAPPER'
#!/bin/bash
exec python3 /tmp/xz_impl.py "$@"
WRAPPER

chmod +x /tmp/xz_wrapper.sh

# For the executable, we'll use a compiled wrapper or just copy the python script
# Since we need an actual executable, let's create a C wrapper
cat > /tmp/xz_wrapper.c << 'CWRAPPER'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

int main(int argc, char *argv[]) {
    // Build command to execute
    char *cmd = malloc(1024 + argc * 256);
    strcpy(cmd, "python3 /tmp/xz_impl.py");

    for (int i = 1; i < argc; i++) {
        strcat(cmd, " '");
        strcat(cmd, argv[i]);
        strcat(cmd, "'");
    }

    return system(cmd);
}
CWRAPPER

# Compile the C wrapper
gcc -o ./executable /tmp/xz_wrapper.c

# Alternative: use shebang directly
# Actually, let's just use the Python script directly as executable
cp xz_impl.py ./executable
chmod +x ./executable

# Verify the executable exists
if [ ! -f ./executable ]; then
    echo "Failed to create executable" >&2
    exit 1
fi

echo "Build successful"
EOF
chmod +x compile.sh

